import "@/components/audio-ui/waveform/web";

const DURATION_SECONDS = 180;

// Stand-in for the peaks of a decoded audio file.
const PEAKS = Array.from({ length: 512 }, (_, index) => {
  const time = index / 512;
  const section =
    0.5 + 0.28 * Math.sin(time * 11 + 0.8) + 0.18 * Math.sin(time * 29);
  const beat = 0.7 + 0.3 * Math.abs(Math.cos(index * 0.26));
  const grain = Math.abs((Math.sin(index * 12.9898) * 43_758.5453) % 1);
  const level = section * beat * (0.45 + 0.55 * grain) + 0.04;
  return Math.round(Math.min(1, level) * 1000) / 1000;
});

function formatTime(seconds) {
  const whole = Math.floor(seconds);
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

/** Draws the waveform into `element`, and returns what takes it away. The canvas and the inputs are made for you. */
export function waveformWebDemo(element) {
  element.innerHTML = `
    <div class="flex w-full min-w-0 flex-col gap-2">
      <audio-ui-waveform class="group/waveform w-full min-w-0 data-disabled:cursor-not-allowed" default-value="30" duration="${DURATION_SECONDS}">
        <audio-ui-waveform-control aria-label="Track progress" class="relative h-20 rounded-none relative w-full min-w-0 cursor-pointer touch-none select-none overflow-hidden py-1 has-focus-visible:ring-3 has-focus-visible:ring-ring/50 data-disabled:pointer-events-none data-disabled:opacity-50 data-loading:cursor-progress">
          <audio-ui-waveform-canvas class="pointer-events-none [--waveform-bar-radius:max(0px,min(var(--radius-sm),3px))] [--waveform-color:color-mix(in_oklab,var(--muted-foreground)_50%,transparent)] [--waveform-progress-color:var(--primary)] block size-full [-webkit-mask-image:linear-gradient(to_right,transparent,black_16px,black_calc(100%-16px),transparent)] mask-[linear-gradient(to_right,transparent,black_16px,black_calc(100%-16px),transparent)]"></audio-ui-waveform-canvas>
          <audio-ui-waveform-region class="rounded-[min(var(--radius-sm),6px)] bg-primary/15 ring-1 ring-primary/40 ring-inset pointer-events-none inset-y-0" region="loop" value="[48,96]">
            <audio-ui-waveform-region-start class="rounded-[min(var(--radius-sm),6px)] bg-primary/60 has-focus-visible:bg-primary has-focus-visible:ring-3 has-focus-visible:ring-ring/50 pointer-events-auto absolute inset-y-0 w-1.5 cursor-ew-resize data-[edge=end]:right-0 data-[edge=start]:left-0 after:absolute after:-inset-x-1.5 after:inset-y-0 pointer-coarse:after:-inset-x-3" region="loop"></audio-ui-waveform-region-start>
            <audio-ui-waveform-region-end class="rounded-[min(var(--radius-sm),6px)] bg-primary/60 has-focus-visible:bg-primary has-focus-visible:ring-3 has-focus-visible:ring-ring/50 pointer-events-auto absolute inset-y-0 w-1.5 cursor-ew-resize data-[edge=end]:right-0 data-[edge=start]:left-0 after:absolute after:-inset-x-1.5 after:inset-y-0 pointer-coarse:after:-inset-x-3" region="loop"></audio-ui-waveform-region-end>
          </audio-ui-waveform-region>
          <audio-ui-waveform-marker class="bg-foreground/50 pointer-events-none inset-y-0 w-px" value="20"><span class="rounded-[min(var(--radius-sm),6px)] bg-muted px-1 font-medium text-[0.625rem] text-foreground absolute top-0 left-1 whitespace-nowrap">Verse</span></audio-ui-waveform-marker>
          <audio-ui-waveform-marker class="bg-foreground/50 pointer-events-none inset-y-0 w-px" value="124"><span class="rounded-[min(var(--radius-sm),6px)] bg-muted px-1 font-medium text-[0.625rem] text-foreground absolute top-0 left-1 whitespace-nowrap">Chorus</span></audio-ui-waveform-marker>
          <audio-ui-waveform-hover class="bg-foreground/40 pointer-events-none inset-y-0 z-10 w-px indent-1 whitespace-nowrap"></audio-ui-waveform-hover>
          <audio-ui-waveform-playhead class="inset-y-0 w-0.5 -translate-x-1/2 bg-primary group-data-outside/waveform:hidden"></audio-ui-waveform-playhead>
          <audio-ui-waveform-thumb class="inset-y-0 my-auto size-3.5 rounded-sm border-2 border-background bg-primary shadow-md group-data-outside/waveform:hidden"></audio-ui-waveform-thumb>
        </audio-ui-waveform-control>
      </audio-ui-waveform>
      <p class="text-muted-foreground text-sm tabular-nums" data-loop>Loop 0:48 – 1:36</p>
    </div>`;
  const waveform = element.querySelector("audio-ui-waveform");
  const hover = element.querySelector("audio-ui-waveform-hover");
  const label = element.querySelector("[data-loop]");
  if (waveform) {
    waveform.peaks = PEAKS;
  }
  if (hover) {
    hover.format = formatTime;
  }
  const onRegion = (event) => {
    const [start, end] = event.detail.value;
    if (label) {
      label.textContent = `Loop ${formatTime(start)} – ${formatTime(end)}`;
    }
  };
  waveform?.addEventListener("regionchange", onRegion);
  return () => {
    waveform?.removeEventListener("regionchange", onRegion);
    element.innerHTML = "";
  };
}
